    &self,
    f: impl Fn(&mut T, E, &mut Window, &mut Context<T>) -> R + 'static,
) -> impl Fn(E, &mut Window, &mut App) -> R + 'static {
    let view = self.entity();
    move |e: E, window: &mut Window, cx: &mut App| {
        view.update(cx, |view, cx| f(view, e, window, cx))
    }
}

